function rng(seed){let a=seed>>>0;return()=>{a+=0x6D2B79F5;let t=a;t=Math.imul(t^t>>>15,t|1);t^=t+Math.imul(t^t>>>7,t|61);return((t^t>>>14)>>>0)/4294967296}}
export const BASS_ROOTS=[28,33,38,43,48,53];
export const nearestBassSample=note=>BASS_ROOTS.reduce((a,b)=>Math.abs(b-note)<Math.abs(a-note)?b:a);
export function bassEnvelope(time,duration){if(time<0||time>duration+.06)return 0;return Math.min(1,time/.006)*Math.min(1,Math.max(0,(duration+.06-time)/.06))}
export function generateBass(song,drums,opt,seed,variant){if(opt.bassEnabled===false)return[];const random=rng(seed^0xb455),events=[];let previousRoot=28;const mode=opt.bassMode==='auto'||!opt.bassMode?['riff','pocket','drive'][variant%3]:opt.bassMode;
 for(const bar of song.bars){const hits=bar.hits.filter(h=>h.pitches.length).sort((a,b)=>a.t-b.t);if(!hits.length&&!bar.held)continue;const rootAt=t=>{let hit;for(const h of hits){if(h.t>t+.015)break;hit=h}if(!hit)return previousRoot;let note=Math.min(...hit.pitches)-12;while(note<23)note+=12;while(note>47)note-=12;return note};
 let positions=[];if(mode==='riff'){positions=hits.map(h=>h.t);if(!positions.length)positions=[0]}else if(mode==='pocket'){positions=[0,...drums.filter(e=>e.note===36&&e.beat>=bar.start&&e.beat<bar.start+bar.length).map(e=>Math.round((e.beat-bar.start)*4)/4).filter((t,i)=>t%1===0||i%3===0)]}else{for(let t=0;t<bar.length;t+=.5)positions.push(t)}
 positions=[...new Set(positions)].filter(t=>t>=0&&t<bar.length&&(bar.held||!hits.length||t>=hits[0].t)).sort((a,b)=>a-b);for(let i=0;i<positions.length;i++){const t=positions[i];let note=rootAt(t);if(mode==='drive'&&variant%3===2&&i%8===7&&+opt.complexity>65)note+=12;const h=hits.find(h=>Math.abs(h.t-t)<.02);const gap=(positions[i+1]??bar.length)-t;const duration=Math.max(.06,Math.min(2,gap*(h?.palm?.5:mode==='pocket'?.85:.75),mode==='riff'&&h?h.duration:Infinity));events.push({beat:bar.start+t,note,duration,velocity:Math.round(85+random()*20),mode});}if(hits.length)previousRoot=rootAt(bar.length);
 }return events;
}
